from typing import Callable


def naive_recursive(n: int) -> int:
    """Simple (very slow) recursive Fibonacci implementation.

    Exponential time; usable only for small n (e.g. n <= 30).
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return naive_recursive(n - 1) + naive_recursive(n - 2)


@lru_cache(maxsize=None)
def cached_recursive(n: int) -> int:
    """Recursive Fibonacci with an LRU cache to make it linear-time.

    Note: uses recursion and therefore may hit Python's recursion limit for
    very large n (typically > 1000). For those sizes prefer iterative().
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return cached_recursive(n - 1) + cached_recursive(n - 2)


def iterative(n: int) -> int:
    """Fast iterative Fibonacci implementation (O(n) time, O(1) extra space).

    Works for very large n (subject to available memory for big integers).
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
